"use client";

import { forwardRef, type CSSProperties, type HTMLAttributes } from "react";
import { kineticTextDefaults, type KineticTextSpecProps } from "../generated/kinetic-text.types";
import { cx } from "../utils/cx";
import { motionVars } from "../utils/motion";
import { splitWords } from "../utils/split-text";

export interface KineticTextProps
  extends KineticTextSpecProps,
    Omit<HTMLAttributes<HTMLSpanElement>, keyof KineticTextSpecProps | "className" | "children"> {
  className?: string;
}

/**
 * Letters that move one after another in a loop (wave, bounce or pulse), staggered by position. Plain
 * CSS. The full text is visually hidden for screen readers and the moving letters are hidden from them.
 */
export const KineticText = forwardRef<HTMLSpanElement, KineticTextProps>(function KineticText(
  {
    children,
    effect = kineticTextDefaults.effect,
    duration = kineticTextDefaults.duration,
    stagger = kineticTextDefaults.stagger,
    isPaused = kineticTextDefaults.isPaused,
    className,
    style,
    ...rest
  },
  ref,
) {
  let n = 0;
  const words = splitWords(children);
  return (
    <span
      {...rest}
      ref={ref}
      data-rdm-paused={isPaused || undefined}
      data-effect={effect}
      className={cx("rdm-kinetic", className)}
      style={{ ...motionVars({ "--rdm-d": `${duration}s`, "--rdm-s": `${stagger}s` }), ...style }}
    >
      <span className="sr-only">{children}</span>
      <span aria-hidden="true">
        {words.map((word, w) => (
          <span key={w}>
            <span className="rdm-word-nowrap">
              {Array.from(word).map((ch) => {
                const i = n++;
                return (
                  <span key={i} className="rdm-kinetic-unit" style={{ "--rdm-i": i } as CSSProperties}>
                    {ch}
                  </span>
                );
              })}
            </span>
            {w < words.length - 1 ? " " : null}
          </span>
        ))}
      </span>
    </span>
  );
});

// Generated by rdloom codegen from specs/kinetic-text.spec.json (v0.1.0).
// Do not edit. Change the spec and run `npm run gen`.

export const kineticTextEffectValues = ["wave", "bounce", "pulse"] as const;

/** Text whose letters move one after another in a loop: a wave, a bounce or a pulse. Plain CSS, staggered by letter position. */
export interface KineticTextSpecProps {
  /**
   * The text. Words never split across lines mid-word.
   */
  children: string;
  /**
   * How each letter moves.
   * @default "wave"
   */
  effect?: "wave" | "bounce" | "pulse";
  /**
   * Seconds for one loop of a single letter.
   * @default 1.6
   */
  duration?: number;
  /**
   * Seconds between one letter starting and the next.
   * @default 0.08
   */
  stagger?: number;
  /**
   * Stops the animation and shows the finished text. Moving content that lasts more than five seconds should be stoppable.
   * @default false
   */
  isPaused?: boolean;
}

export const kineticTextDefaults = {
  effect: "wave",
  duration: 1.6,
  stagger: 0.08,
  isPaused: false,
} as const;

export const kineticTextMeta = {
  "name": "KineticText",
  "version": "0.1.0",
  "status": "experimental",
  "role": "group"
} as const;
